-- Spaces around commas in all songbooks (2026-10-25): exactly one space after a comma ("ручья,-" ->
-- "ручья, -", "себя,(как" -> "себя, (как"), none before it; "идти,," and ",." fixed.
-- Repeat signs ":,:" and numbers like "1,5" stay. Each fix replaces one line of one song and is
-- skipped when that line was changed since.
UPDATE Songs SET song_text = replace(song_text, 'Все, что тайно и сокрыто,- в день явления Его', 'Все, что тайно и сокрыто, - в день явления Его') WHERE songbook_id = (SELECT id FROM Songbooks WHERE name = 'Песнь Возрождения 3300') AND number = 797 AND instr(song_text, 'Все, что тайно и сокрыто,- в день явления Его') > 0;
