UPDATE Songs SET song_text = replace(song_text, '"О, Авва Отче»,- ', '"О, Авва Отче», - ') WHERE songbook_id = (SELECT id FROM Songbooks WHERE name = 'Хоровые песни') AND number = 70 AND instr(song_text, '"О, Авва Отче»,- ') > 0;
